#pragma once

#include <wx/eventfilter.h>

namespace Slic3r::GUI {
class MainFrame;
}

namespace Slic3r::GUI::JusPrin {

// OrcaSlicer's update check, which GUI_App runs at startup, looks for
// OrcaSlicer releases and opens its "New version of Orca Slicer" window to
// offer them. JusPrin must not offer OrcaSlicer releases, so this filter
// drops the check's result before any handler sees it. An event filter runs
// ahead of every bound handler, so this does not depend on the order in
// which OrcaSlicer and JusPrin bind theirs. JusPrin's own update check
// (Preferences > Updates) replaces it.
class OrcaUpdateFilter : public wxEventFilter
{
public:
    int FilterEvent(wxEvent& event) override;
};

// Installs the filter for the lifetime of `frame`.
void filter_orca_update_window(MainFrame& frame);

} // namespace Slic3r::GUI::JusPrin

#include "OrcaUpdateFilter.hpp"

#include "slic3r/GUI/MainFrame.hpp"
#include "slic3r/Utils/PresetUpdater.hpp"

namespace Slic3r::GUI::JusPrin {

int OrcaUpdateFilter::FilterEvent(wxEvent& event)
{
    return event.GetEventType() == EVT_SLIC3R_VERSION_ONLINE ? Event_Processed : Event_Skip;
}

void filter_orca_update_window(MainFrame& frame)
{
    auto* filter = new OrcaUpdateFilter;
    wxEvtHandler::AddFilter(filter);
    // Recreating the GUI builds the new frame before destroying the old one,
    // so each frame owns its own filter and removes only that one.
    frame.Bind(wxEVT_DESTROY, [&frame, filter](wxWindowDestroyEvent& event) {
        if (event.GetEventObject() == &frame) {
            wxEvtHandler::RemoveFilter(filter);
            delete filter;
        }
        event.Skip();
    });
}

} // namespace Slic3r::GUI::JusPrin

